select u2.nom_usuari, u2.cognom1_usuari, u2.cognom2_usuari, q.nota  from usuaris u join qualificacions q on u.id_usuari = q.id_professor join moduls m on q.id_modul = m.id_modul join usuaris u2 on u2.id_usuari = q.id_alumne
join grups g on g.id_tutor = u.id_usuari where  u.nom_usuari = 'Berta' and u.cognom1_usuari ='Bertin' and u.cognom2_usuari = 'Bergara' and m.codi_modul = 'M1709' and m.id_cicle = 'ASIX' and q.convocatoria = 1 and u2.id_grup = g.id_grup
